#!/usr/bin/env bash
# ─────────────────────────────────────────────────────────────────────────
# CGPA Pilot - v1.0.13 updater (Mac / Linux / WSL)
#
#   Double-click me, or in a terminal run:   bash apply-v1.0.13.sh
#
#   This file carries the whole v1.0.13 patch inside it. It will:
#     1. check you are inside the CGPA-pilot folder and main is up to date
#     2. refuse to run if you have OTHER uncommitted work (I never touch it)
#     3. apply the v1.0.13 patch, commit it, and push it to main
# ─────────────────────────────────────────────────────────────────────────
set -u
cd "$(dirname "$0")" || exit 1

echo "============================================"
echo " CGPA Pilot updater - v1.0.13"
echo " (streaming AI + history + admin diagnostics)"
echo "============================================"
echo

[ -f package.json ] || {
  echo " ERROR: put this file INSIDE your CGPA-pilot folder"
  echo " (the folder that contains package.json), then run it again."
  exit 1
}
command -v git >/dev/null 2>&1 || { echo " ERROR: git is not installed."; exit 1; }
echo " Repo folder: $PWD"
echo

# --- Safety: never touch other uncommitted work ---
if [ -n "$(git status --porcelain | grep -v -e 'apply-v1.0.13.sh' -e 'fix-cgpa-v1.0.13.bat' -e 'v1.0.13.patch' -e '\.v1013' | head -n 1)" ]; then
  echo " STOP - this folder has other uncommitted changes:"
  git status --short
  echo
  echo " I never touch your work. Commit or stash those first, then run me again."
  exit 1
fi

echo " Checking main is up to date..."
git checkout main || exit 1
git pull origin main || { echo; echo " Could not update from GitHub - check your internet connection."; exit 1; }

# --- Already applied? ---
if grep -q 'ai_errors' worker/src/db.ts; then
  echo
  echo " v1.0.13 is already applied - nothing to do. You are up to date."
  exit 0
fi

echo
echo " Preparing the v1.0.13 patch (embedded in this file)..."
rm -f .v1013.b64 .v1013.patch
